package com.visibilityenhancer;

import java.util.Arrays;

/**
 * Reusable 1024-int outline blocks, adapted from RuneLite's IntBlockBuffer.
 * Kept local because the upstream class is package-private.
 */
final class OutlinePixelBuffer
{
	public static final int BLOCK_BITS = 10;
	public static final int BLOCK_SIZE = 1 << BLOCK_BITS;

	private int[] memory = new int[0];
	private int[] unusedBlockIndices = new int[0];
	private int unusedBlockIndicesLength;

	private void increaseBlockCount()
	{
		int currBlockCount = memory.length >> BLOCK_BITS;
		int newBlockCount = Math.max(1, currBlockCount * 2);
		memory = Arrays.copyOf(memory, newBlockCount * BLOCK_SIZE);
		unusedBlockIndices = Arrays.copyOf(unusedBlockIndices, newBlockCount);
		for (int i = currBlockCount; i < newBlockCount; i++)
		{
			unusedBlockIndices[unusedBlockIndicesLength++] = i;
		}
	}

	/**
	 * Retrieves the whole memory buffer.
	 */
	public int[] getMemory()
	{
		return memory;
	}

	/**
	 * Marks a new block as used.
	 *
	 * @return The index of the block.
	 */
	public int useNewBlock()
	{
		if (unusedBlockIndicesLength == 0)
		{
			increaseBlockCount();
		}

		return unusedBlockIndices[--unusedBlockIndicesLength];
	}

	/**
	 * Marks a block as unused.
	 *
	 * @param index The index of the block. The block should be in use before calling this method.
	 */
	public void freeBlock(int index)
	{
		unusedBlockIndices[unusedBlockIndicesLength++] = index;
	}
}

package com.visibilityenhancer;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.runelite.api.Player;

/** Packs chat upward, with a small release margin to avoid one-pixel overlap flicker. */
final class OverheadTextLayout
{
   private static final int GAP = 2;
   private static final int RELEASE_MARGIN_X = 2;
   private static final int RELEASE_MARGIN_Y = 6;
   private final List<Rectangle> occupied = new ArrayList<>();
   private Set<Player> raisedLastFrame = new HashSet<>();
   private Set<Player> raisedThisFrame = new HashSet<>();

   void beginFrame()
   {
      occupied.clear();
      Set<Player> scratch = raisedLastFrame;
      raisedLastFrame = raisedThisFrame;
      raisedThisFrame = scratch;
      raisedThisFrame.clear();
   }

   void clear()
   {
      occupied.clear();
      raisedLastFrame.clear();
      raisedThisFrame.clear();
   }

   void reserve(Rectangle bounds)
   {
      occupied.add(bounds);
   }

   Rectangle place(Player player, Rectangle naturalBounds)
   {
      Rectangle placed = new Rectangle(naturalBounds);
      Rectangle probe = new Rectangle();
      boolean wasRaised = raisedLastFrame.contains(player);
      boolean moved;
      do
      {
         moved = false;
         probe.setBounds(placed);
         // A previously lifted message needs clear separation before dropping back.
         // Always start from this frame's anchor, never a cached screen position.
         if (wasRaised) probe.grow(RELEASE_MARGIN_X, RELEASE_MARGIN_Y);
         for (Rectangle bounds : occupied)
         {
            int above = bounds.y - placed.height - GAP;
            if (above < placed.y && probe.intersects(bounds))
            {
               placed.y = above;
               moved = true;
               break;
            }
         }
      }
      while (moved);

      if (placed.y < naturalBounds.y) raisedThisFrame.add(player);
      occupied.add(placed);
      return placed;
   }
}

package com.visibilityenhancer;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import net.runelite.api.Actor;
import net.runelite.api.NPC;
import net.runelite.api.Player;
import net.runelite.api.WorldView;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;

/** Per-frame scene-selected actors, not guesses based on the affected-player collection order. */
final class StackedHighlightTracker
{
   private final Map<TileKey, Actor> actors = new HashMap<>();
   private final Set<TileKey> visibleTiles = new HashSet<>();
   private boolean enabled;

   void beginFrame(boolean enabled)
   {
      this.enabled = enabled;
      actors.clear();
      visibleTiles.clear();
   }

   void record(Actor actor, boolean visible)
   {
      if (!enabled) return;
      TileKey tile = tileKey(actor);
      if (tile == null) return;

      // A visible actor beats one hidden by our 0% draw skip. For multiple draws
      // on the same tile, retain the later submission. This is not a per-pixel depth test.
      if (visible || !visibleTiles.contains(tile))
      {
         actors.put(tile, actor);
         if (visible) visibleTiles.add(tile);
      }
   }

   Actor preferredActor(Actor actor)
   {
      return enabled ? actors.get(tileKey(actor)) : null;
   }

   static TileKey tileKey(Actor actor)
   {
      if (!(actor instanceof Player) && !(actor instanceof NPC)) return null;
      WorldPoint world = actor.getWorldLocation();
      if (world == null) return null;
      LocalPoint local = actor.getLocalLocation();
      // Local coordinates follow the rendered movement, unlike the server's destination tile.
      return new TileKey(actor.getWorldView(), world.getPlane(),
              local == null ? world.getX() : local.getSceneX(),
              local == null ? world.getY() : local.getSceneY(), local != null, actor instanceof NPC);
   }

   static final class TileKey
   {
      private final WorldView view;
      private final int plane, x, y;
      private final boolean local, npc;

      private TileKey(WorldView view, int plane, int x, int y, boolean local, boolean npc)
      {
         this.view = view;
         this.plane = plane;
         this.x = x;
         this.y = y;
         this.local = local;
         this.npc = npc;
      }

      @Override
      public boolean equals(Object other)
      {
         if (!(other instanceof TileKey)) return false;
         TileKey key = (TileKey) other;
         return view == key.view && plane == key.plane && x == key.x && y == key.y
                 && local == key.local && npc == key.npc;
      }

      @Override
      public int hashCode()
      {
         int hash = 31 * (31 * (31 * System.identityHashCode(view) + plane) + x) + y;
         return 31 * (31 * hash + (local ? 1 : 0)) + (npc ? 1 : 0);
      }
   }
}

