   @Getter
   @AllArgsConstructor
   public static class CustomHitsplat
   {
      private final int type;
      private final int amount;
      private final int disappearsOnGameCycle;
   }

   @Getter
   private final Map<Player, List<CustomHitsplat>> customHitsplats = new HashMap<>();

   @Override
   protected void startUp()
   {
      pendingPlayerUpdates.clear();
      overlayManager.add(overlay);
      overlayManager.add(overheadOverlay);
      overlayManager.add(outlineOverlay);
      hooks.registerRenderableDrawListener(drawListener);
      keyManager.registerKeyListener(hotkeyListener);
      keyManager.registerKeyListener(peekListener);
      pluginToggledOn = true;
      hotkeyHeld = false;
      peekHeld = false;
      wasActive = false;
      currentRegionId = -1;

      gpuOpacityEnabled = true;
      clientThread.invokeLater(this::syncGpuDrawCallbacks);

      isProjectileOverrideActive = false;
      if (pluginManager != null)
      {
         for (Plugin p : pluginManager.getPlugins())
         {
            if ("Projectile Override".equals(p.getName()))
            {
               // isPluginEnabled checks if it is currently active in the user's config
               isProjectileOverrideActive = pluginManager.isPluginEnabled(p);
               break;
            }
         }
      }
   }

   @Override
   protected void shutDown()
   {
      gpuOpacityEnabled = false;
      overlayManager.remove(overlay);
      overlayManager.remove(overheadOverlay);
      overlayManager.remove(outlineOverlay);
      hooks.unregisterRenderableDrawListener(drawListener);
      keyManager.unregisterKeyListener(hotkeyListener);
      keyManager.unregisterKeyListener(peekListener);

      clientThread.invokeLater(() ->
      {
         return finishRendererShutdown();
      });

      cachedLocalPlayer = null;
      wasActive = false;
      currentRegionId = -1;
   }

   public boolean isActive()
   {
      if (client.getGameState() != GameState.LOGGED_IN)
      {
         return false;
      }

      if (!pluginToggledOn)
      {
         return false;
      }

      if (peekHeld)
      {
         return true;
      }

      if (!config.enableAreaFiltering())
      {
         return true;
      }

      switch (currentRegionId)
      {
         case 12613:
            return config.tobMaiden();
         case 13125:
            return config.tobBloat();
         case 13122:
            return config.tobNylo();
         case 13123:
         case 13379:
            return config.tobSote();
         case 12612:
            return config.tobXarpus();
         case 12611:
            return config.tobVerzik();

         case 15700:
            return config.toaZebak();
         case 14164:
            return config.toaKephri();
         case 14676:
            return config.toaAkkha();
         case 15186: // Path of Apmeken (Monkey Puzzle)
         case 15188:
            return config.toaBaba();
         case 15184:
         case 15696:
            return config.toaWardens();

         case 12889:
            return config.coxOlm();

         case 11601:
            return config.otherNex();
         case 15515:
            return config.otherNightmare();
         case 11669:
            return config.otherRoyalTitans();
         case 7216:
            return config.otherFortisColosseum();
      }

      if (client.getVarbitValue(Varbits.IN_RAID) == 1)
      {
         return config.coxRest();
      }

      return false;
   }

   @Subscribe
   public void onHitsplatApplied(HitsplatApplied event)
   {
      if (!isActive())
      {
         return;
      }

      if (event.getActor() instanceof Player)
      {
         Player p = (Player) event.getActor();
         Hitsplat hitsplat = event.getHitsplat();
         if (hitsplat == null) return;

         // A blocked attack still counts, even when zero hitsplats are hidden. Healing,
         // stat/resource changes and unknown types are not evidence of incoming damage.
         if (HitsplatStyle.isCombatHit(hitsplat.getHitsplatType()))
         {
            combatTimerMap.put(p, client.getTickCount());
         }

         if (config.othersTransparentPrayers() && ghostedPlayers.contains(p))
         {
            int amount = hitsplat.getAmount();
            int currentCycle = client.getGameCycle();
            int disappearsOnGameCycle = hitsplat.getDisappearsOnGameCycle();

            if (hitsplat.getHitsplatType() < 0 || disappearsOnGameCycle <= currentCycle
                    || (amount == 0 && config.hideZeroHitsplats()))
            {
               return;
            }

            List<CustomHitsplat> list = customHitsplats.computeIfAbsent(p, k -> new ArrayList<>());
            list.removeIf(h -> currentCycle >= h.getDisappearsOnGameCycle());
            // Copy values: do not retain a client-owned hitsplat that may be reused.
            CustomHitsplat newHit = new CustomHitsplat(hitsplat.getHitsplatType(), amount, disappearsOnGameCycle);

            if (list.size() < 4)
            {
               list.add(newHit);
            }
            else
            {
               int targetIndex = -1;
               boolean foundZero = false;

               for (int i = 0; i < list.size(); i++)
               {
                  CustomHitsplat h = list.get(i);
                  if (h.getAmount() == 0)
                  {
                     if (!foundZero)
                     {
                        targetIndex = i;
                        foundZero = true;
                     }
                     else if (h.getDisappearsOnGameCycle() < list.get(targetIndex).getDisappearsOnGameCycle())
                     {
                        targetIndex = i;
                     }
                  }
                  else if (!foundZero)
                  {
                     if (targetIndex == -1 || h.getDisappearsOnGameCycle() < list.get(targetIndex).getDisappearsOnGameCycle())
                     {
                        targetIndex = i;
                     }
                  }
               }

               if (amount == 0 && !foundZero)
               {
                  return;
               }

               if (targetIndex != -1)
               {
                  list.set(targetIndex, newHit);
               }
            }
         }
      }
   }

   // Called before overhead layout as well as on game ticks, so expired hits neither
   // draw nor reserve a layout slot while waiting for the next server tick.
   void pruneCustomHitsplats()
   {
      if (customHitsplats.isEmpty()) return;
      if (!isActive() || !config.othersTransparentPrayers())
      {
         customHitsplats.clear();
         return;
      }
      int currentCycle = client.getGameCycle();
      customHitsplats.values().removeIf(list ->
      {
         list.removeIf(h -> currentCycle >= h.getDisappearsOnGameCycle());
         return list.isEmpty();
      });
   }

   @Subscribe
   public void onAnimationChanged(AnimationChanged event)
   {
      if (!isActive())
      {
         return;
      }

      if (event.getActor() instanceof Player)
      {
         Player p = (Player) event.getActor();
         int anim = p.getAnimation();

         // If the animation is not idle, and NOT a skilling/utility animation
         if (anim != -1 && !EXEMPT_ANIMATIONS.contains(anim))
         {
            combatTimerMap.put(p, client.getTickCount());
         }
